const E=new TextEncoder(),D=new TextDecoder();
const J=(d,s=200,h={})=>new Response(JSON.stringify(d),{status:s,headers:{'content-type':'application/json;charset=utf-8',...h}});
const B=(m,s=400)=>J({error:m},s);
const clean=(x,n=5000)=>String(x??'').trim().slice(0,n),mail=x=>String(x??'').trim().toLowerCase();
const b64=b=>btoa(String.fromCharCode(...new Uint8Array(b))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
const ub=s=>{s=s.replace(/-/g,'+').replace(/_/g,'/');while(s.length%4)s+='=';return Uint8Array.from(atob(s),c=>c.charCodeAt(0))};
const rand=()=>b64(crypto.getRandomValues(new Uint8Array(24)));
const shortRand=()=>b64(crypto.getRandomValues(new Uint8Array(4)));

async function uniqueShortToken(env){for(let i=0;i<8;i++){const t=shortRand();if(!await env.DB.prepare('SELECT id FROM share_tokens WHERE token=?').bind(t).first())return t}return shortRand()}
async function hmac(sec,data){const k=await crypto.subtle.importKey('raw',E.encode(sec),{name:'HMAC',hash:'SHA-256'},false,['sign']);return b64(await crypto.subtle.sign('HMAC',k,E.encode(data)))}
async function makeTok(sec,p){const x=b64(E.encode(JSON.stringify(p)));return x+'.'+await hmac(sec,x)}
async function readTok(sec,t){if(!sec||!t)return null;const [x,s]=t.split('.');if(!x||!s)return null;try{if((await hmac(sec,x))!==s)return null;const p=JSON.parse(D.decode(ub(x)));return p.exp>Date.now()?p:null}catch{return null}}
async function phash(p,s){s=s?ub(s):crypto.getRandomValues(new Uint8Array(16));const k=await crypto.subtle.importKey('raw',E.encode(p),'PBKDF2',false,['deriveBits']);const z=await crypto.subtle.deriveBits({name:'PBKDF2',salt:s,iterations:100000,hash:'SHA-256'},k,256);return{hash:b64(z),salt:b64(s)}}
const cookie=(v,max=604800)=>`jn_session=${v}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${max}`;
async function body(r){try{return await r.json()}catch{return{}}}
async function userOf(env,req){const raw=req.headers.get('Cookie')?.match(/(?:^|;\s*)jn_session=([^;]+)/)?.[1];const t=await readTok(env.SESSION_SECRET,raw);if(!t)return null;return env.DB.prepare('SELECT id,name,email,role,status FROM users WHERE id=?').bind(t.uid).first()}
async function planOf(env,uid){try{const r=await env.DB.prepare('SELECT plan FROM user_plans WHERE user_id=?').bind(uid).first();return r?.plan==='ultimate'?'ultimate':'premium'}catch{return'premium'}}
const limits=p=>p==='ultimate'?{up:6,down:6,members:20}:{up:3,down:2,members:5};
const price=(p,e)=>p==='ultimate'?Number(e.ULTIMATE_PRICE||100000):Number(e.PREMIUM_PRICE||50000);
const pname=p=>[p?.title_prefix,p?.first_name,p?.last_name,p?.title_suffix].filter(Boolean).join(' ');
const age=(b,d='')=>{if(!b)return null;const a=new Date(b+'T00:00:00'),z=d?new Date(d+'T00:00:00'):new Date();if(Number.isNaN(a.getTime())||Number.isNaN(z.getTime()))return null;let n=z.getFullYear()-a.getFullYear();if(z.getMonth()<a.getMonth()||(z.getMonth()===a.getMonth()&&z.getDate()<a.getDate()))n--;return n<0?null:n};
async function tree(env,id){return env.DB.prepare('SELECT * FROM family_trees WHERE id=?').bind(id).first()}
async function refreshAutoTreeName(env,tid){const t=await tree(env,tid);if(!t||!Number(t.auto_name))return;const r=await env.DB.prepare("SELECT p.* FROM persons p WHERE p.tree_id=? AND p.gender='male' AND NOT EXISTS(SELECT 1 FROM relationships r WHERE r.tree_id=p.tree_id AND r.to_person_id=p.id AND r.type='parent') ORDER BY CASE WHEN p.birth_date='' THEN 1 ELSE 0 END,p.birth_date,p.id LIMIT 1").bind(tid).first();const n=r?pname(r):'Silsilah Keluarga';await env.DB.prepare('UPDATE family_trees SET name=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(n,tid).run()}
async function ensureTreeRoot(env,tid){const t=await tree(env,tid);if(!t)return null;let cur=Number(t.root_person_id||0);if(cur){const cp=await env.DB.prepare("SELECT id,gender FROM persons WHERE id=? AND tree_id=?").bind(cur,tid).first();if(cp&&cp.gender==='male'){const maleParent=await env.DB.prepare("SELECT p.id FROM relationships r JOIN persons p ON p.id=r.from_person_id WHERE r.tree_id=? AND r.to_person_id=? AND r.type='parent' AND p.gender='male' ORDER BY r.id LIMIT 1").bind(tid,cur).first();if(!maleParent)return cur;cur=Number(maleParent.id)}}let r=await env.DB.prepare("SELECT p.id FROM persons p WHERE p.tree_id=? AND p.gender='male' AND NOT EXISTS(SELECT 1 FROM relationships x JOIN persons pp ON pp.id=x.from_person_id WHERE x.tree_id=p.tree_id AND x.to_person_id=p.id AND x.type='parent' AND pp.gender='male') ORDER BY CASE WHEN p.sibling_order=0 THEN 1 ELSE 0 END,p.sibling_order,CASE WHEN p.birth_date='' THEN 1 ELSE 0 END,p.birth_date,p.id LIMIT 1").bind(tid).first();if(!r)r=await env.DB.prepare("SELECT p.id FROM persons p WHERE p.tree_id=? AND NOT EXISTS(SELECT 1 FROM relationships x WHERE x.tree_id=p.tree_id AND x.to_person_id=p.id AND x.type='parent') ORDER BY p.id LIMIT 1").bind(tid).first();const id=Number(r?.id||cur||0)||null;await env.DB.prepare('UPDATE family_trees SET root_person_id=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').bind(id,tid).run();return id}
async function validateSpouse(env,tid,a,z){const pa=await env.DB.prepare('SELECT id,gender,death_date FROM persons WHERE id=? AND tree_id=?').bind(a,tid).first(),pz=await env.DB.prepare('SELECT id,gender,death_date FROM persons WHERE id=? AND tree_id=?').bind(z,tid).first();if(!pa||!pz)return {error:'Anggota relasi tidak ditemukan.'};if(pa.gender==='other'||pz.gender==='other'||pa.gender===pz.gender)return {error:'Relasi pasangan harus antara laki-laki (suami) dan perempuan (istri).'};const husband=pa.gender==='male'?pa:pz,wife=pa.gender==='female'?pa:pz;const active=await env.DB.prepare("SELECT r.id,p.id partner_id,p.gender,p.death_date FROM relationships r JOIN persons p ON p.id=CASE WHEN r.from_person_id=? THEN r.to_person_id ELSE r.from_person_id END WHERE r.tree_id=? AND (r.from_person_id=? OR r.to_person_id=?) AND r.type='spouse' AND COALESCE(r.spouse_status,'active')='active' AND COALESCE(r.end_date,'')='' LIMIT 1").bind(wife.id,tid,wife.id,wife.id).first();if(active){if(active.death_date){await env.DB.prepare("UPDATE relationships SET spouse_status='ended',end_date=COALESCE(end_date,?) WHERE id=?").bind(active.death_date,active.id).run()}else{return {error:'Istri tersebut masih memiliki suami yang aktif. Selesaikan hubungan pasangan sebelumnya terlebih dahulu.'}}}return {husband,wife}}
async function graph(env,tid){const ps=(await env.DB.prepare('SELECT * FROM persons WHERE tree_id=?').bind(tid).all()).results||[],rs=(await env.DB.prepare('SELECT * FROM relationships WHERE tree_id=?').bind(tid).all()).results||[];const pa=new Map(),ch=new Map(),sp=new Map();const add=(m,k,v)=>{if(!m.has(k))m.set(k,[]);m.get(k).push(v)};for(const r of rs){if(r.type==='parent'){add(pa,r.to_person_id,r.from_person_id);add(ch,r.from_person_id,r.to_person_id)}else if(r.type==='spouse'){add(sp,r.from_person_id,r.to_person_id);add(sp,r.to_person_id,r.from_person_id)}}return{ps,rs,pa,ch,sp}}
function walk(start,map,n){const o=new Map([[start,0]]),q=[[start,0]];while(q.length){const[x,d]=q.shift();if(d>=n)continue;for(const y of map.get(x)||[])if(!o.has(y)){o.set(y,d+1);q.push([y,d+1])}}return o}
function siblings(start,g){const s=new Set();for(const p of g.pa.get(start)||[])for(const c of g.ch.get(p)||[])if(c!==start)s.add(c);return s}

function generationMap(start,g,n){const dist=new Map([[start,0]]),q=[start];while(q.length){const x=q.shift(),d=dist.get(x);if(Math.abs(d)>n)continue;for(const y of g.pa.get(x)||[])if(!dist.has(y)){dist.set(y,d-1);q.push(y)}for(const y of g.ch.get(x)||[])if(!dist.has(y)){dist.set(y,d+1);q.push(y)}for(const y of g.sp.get(x)||[])if(!dist.has(y)){dist.set(y,d);q.push(y)}for(const par of g.pa.get(x)||[])for(const sib of g.ch.get(par)||[])if(!dist.has(sib)){dist.set(sib,d);q.push(sib)}}return dist}
function memberScope(start,g,up=3,down=2){const ids=new Set([start]);for(const x of walk(start,g.pa,up).keys())ids.add(x);for(const x of walk(start,g.ch,down).keys())ids.add(x);const ss=siblings(start,g);for(const x of ss)ids.add(x);for(const x of ss)for(const y of walk(x,g.ch,2).keys())ids.add(y);for(const x of ss)for(const y of g.sp.get(x)||[])ids.add(y);for(const x of g.sp.get(start)||[]){ids.add(x);for(const y of walk(x,g.ch,down).keys())ids.add(y)}for(const x of [...ids])for(const y of g.sp.get(x)||[])ids.add(y);return ids}
function memberViewRoot(t,g,ids){const allowed=Array.from(ids).map(Number),set=new Set(allowed);const explicit=Number(t.root_person_id||0);if(explicit&&set.has(explicit)){const ep=g.ps.find(p=>Number(p.id)===explicit);if(ep&&ep.gender==='male')return explicit}const maleRoots=g.ps.filter(p=>set.has(Number(p.id))&&p.gender==='male'&&!(g.pa.get(p.id)||[]).some(x=>set.has(Number(x))&&g.ps.find(q=>Number(q.id)===Number(x))?.gender==='male')).sort((a,b)=>{const da=walk(a.id,g.pa,99).size,db=walk(b.id,g.pa,99).size;return db-da||Number(a.sibling_order||0)-Number(b.sibling_order||0)||String(pname(a)).localeCompare(String(pname(b)))||a.id-b.id});return Number(maleRoots[0]?.id||0)||Number(allowed[0]||0)||null}
async function membership(env,tid,uid){return env.DB.prepare("SELECT tm.*,p.first_name,p.last_name FROM tree_members tm JOIN persons p ON p.id=tm.person_id WHERE tm.tree_id=? AND tm.user_id=? AND tm.status='active'").bind(tid,uid).first()}
async function audit(env,tid,uid,a,t,id,details=''){try{await env.DB.prepare('INSERT INTO audit_logs(tree_id,actor_user_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?,?)').bind(tid,uid,a,t,id||null,details).run()}catch{}}
async function ownerAccess(u,t){return u?.role==='member'&&t.created_by===u.id}
async function scoped(env,u,t){if(u.role!=='member'||t.created_by===u.id)return null;const m=await membership(env,t.id,u.id);if(!m)return null;const g=await graph(env,t.id),p=await planOf(env,t.created_by);return{m,g,ids:memberScope(m.person_id,g,limits(p).up,limits(p).down),plan:p,planUp:limits(p).up,planDown:limits(p).down}}
async function branchById(env,bid){return env.DB.prepare('SELECT b.*,t.created_by tree_owner,t.name tree_name,a.first_name anchor_first_name,a.last_name anchor_last_name FROM family_branches b JOIN family_trees t ON t.id=b.tree_id JOIN persons a ON a.id=b.anchor_person_id WHERE b.id=?').bind(bid).first()}
async function branchRows(env,bid){return (await env.DB.prepare(`SELECT o.*,a.first_name anchor_first_name,a.last_name anchor_last_name,l.first_name linked_first_name,l.last_name linked_last_name FROM optional_lineages o JOIN persons a ON a.id=o.anchor_person_id JOIN persons l ON l.id=o.linked_person_id WHERE o.branch_id=? ORDER BY o.sibling_order,o.id`).bind(bid).all()).results||[]}
function branchRelations(rows){return rows.map(x=>{const a=Number(x.anchor_person_id),l=Number(x.linked_person_id),label=String(x.relation_label||'').toLowerCase();if(label==='anak')return{id:-Number(x.id),from_person_id:a,to_person_id:l,type:'parent'};if(['ayah','ibu','kakek','nenek'].includes(label))return{id:-Number(x.id),from_person_id:l,to_person_id:a,type:'parent'};if(['suami','istri','pasangan'].includes(label))return{id:-Number(x.id),from_person_id:a,to_person_id:l,type:'spouse'};return{id:-Number(x.id),from_person_id:a,to_person_id:l,type:'sibling'};})}
function branchGeneration(rows,base){const rs=branchRelations(rows),pa=new Map(),ch=new Map(),sp=new Map(),sib=new Map(),add=(m,k,v)=>{if(!m.has(k))m.set(k,[]);m.get(k).push(v)};for(const r of rs){if(r.type==='parent'){add(pa,r.to_person_id,r.from_person_id);add(ch,r.from_person_id,r.to_person_id)}else if(r.type==='spouse'){add(sp,r.from_person_id,r.to_person_id);add(sp,r.to_person_id,r.from_person_id)}else add(sib,r.from_person_id,r.to_person_id)}const d=new Map([[Number(base),0]]),q=[Number(base)];while(q.length){const x=q.shift(),n=d.get(x);if(n<-2||n>2)continue;for(const y of pa.get(x)||[])if(!d.has(y)){d.set(y,n-1);q.push(y)}for(const y of ch.get(x)||[])if(!d.has(y)){d.set(y,n+1);q.push(y)}for(const y of sp.get(x)||[])if(!d.has(y)){d.set(y,n);q.push(y)}for(const y of sib.get(x)||[])if(!d.has(y)){d.set(y,n);q.push(y)}}return d}
async function branchAllowed(env,u,b){if(!b)return false;if(u.role==='owner'||b.tree_owner===u.id)return true;const mm=await membership(env,b.tree_id,u.id);if(!mm)return false;if(Number(mm.person_id)===Number(b.anchor_person_id))return true;const sc=await scoped(env,u,await tree(env,b.tree_id));return !!sc?.ids.has(Number(b.anchor_person_id))}
async function branchScopeIds(env,bid){const rows=await branchRows(env,bid);const ids=new Set();for(const x of rows){ids.add(Number(x.anchor_person_id));ids.add(Number(x.linked_person_id))}const b=await branchById(env,bid);if(b)ids.add(Number(b.anchor_person_id));return ids}
async function seedBranch(env,bid,tid,anchor){const g=await graph(env,tid),ids=memberScope(anchor,g,2,2);for(const id of ids){await env.DB.prepare('INSERT OR IGNORE INTO branch_members(branch_id,person_id,role) VALUES(?,?,?)').bind(bid,id,Number(id)===Number(anchor)?'anchor':'member').run()}for(const r of g.rs){if(!ids.has(Number(r.from_person_id))||!ids.has(Number(r.to_person_id)))continue;let label='';if(r.type==='parent')label='Anak';else if(r.type==='spouse')label='Pasangan';if(label)await env.DB.prepare('INSERT OR IGNORE INTO optional_lineages(tree_id,branch_id,anchor_person_id,linked_person_id,relation_label,sibling_order) VALUES(?,?,?,?,?,?)').bind(tid,bid,Number(r.from_person_id),Number(r.to_person_id),label,0).run()}for(const p of ids){for(const s of g.ch.get(p)||[]){if(!ids.has(Number(s)))continue;for(const t of g.ch.get(p)||[]){if(!ids.has(Number(t))||Number(s)===Number(t))continue;await env.DB.prepare('INSERT OR IGNORE INTO optional_lineages(tree_id,branch_id,anchor_person_id,linked_person_id,relation_label,sibling_order) VALUES(?,?,?,?,?,?)').bind(tid,bid,Number(s),Number(t),'Saudara',0).run()}}}}
