 "CREATE TABLE IF NOT EXISTS branch_members (id INTEGER PRIMARY KEY AUTOINCREMENT, branch_id INTEGER NOT NULL, person_id INTEGER NOT NULL, role TEXT NOT NULL DEFAULT 'member', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(branch_id,person_id), FOREIGN KEY(branch_id) REFERENCES family_branches(id) ON DELETE CASCADE, FOREIGN KEY(person_id) REFERENCES persons(id) ON DELETE CASCADE)",
 "CREATE TABLE IF NOT EXISTS share_tokens (id INTEGER PRIMARY KEY AUTOINCREMENT, tree_id INTEGER NOT NULL UNIQUE, token TEXT NOT NULL UNIQUE, is_public INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(tree_id) REFERENCES family_trees(id) ON DELETE CASCADE)",
